package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.nio.file.*;import java.util.*;
/** Native two-page release wizard: complete side sets, snapshot preview and explicit signing. */
public final class PublicationScreen79 extends MaredScreen {
 private final Screen previous;private final PublicationService79 service=new PublicationService79();private final JsonObject prefs;private String owner,clientValue,serverValue,labelValue;private long ttl=86400;private int page,left,w,top,scroll,maxScroll;private EditBox root,client,server,label;private final List<Button> buttons=new ArrayList<>();private Button author;
 public PublicationScreen79(Screen previous,String owner){super(tr("title"));this.previous=previous;this.owner=owner;prefs=DedicatedPanelService75.preferences();clientValue=pref("client","");serverValue=pref("server","");labelValue=pref("label","r2");}
 private static Component tr(String key,Object...args){return Component.translatable("mared.publication79."+key,args);}
 private String pref(String key,String fallback){try{return prefs.get("publication79"+key).getAsString();}catch(Exception bad){return fallback;}}
 private Button button(String key,int x,int y,int width,Runnable action){Button b=addRenderableWidget(Button.builder(tr(key),a->action.run()).bounds(x,y,width,20).build());buttons.add(b);return b;}
 private EditBox field(String key,int y,String value,boolean browse){EditBox e=addRenderableWidget(new EditBox(font,left+100,y,w-100-(browse?34:0),20,tr(key)));e.setMaxLength(browse?4096:40);e.setValue(value);if(browse)button("browse",left+w-30,y,30,()->browse(e));return e;}
 @Override protected void init(){collect();buttons.clear();w=Math.max(250,Math.min(680,width-24));left=(width-w)/2;button(page==0?"settings":"preview_page",left,32,w,()->{collect();page=1-page;scroll=0;rebuildWidgets();});
  if(page==0){root=field("root",58,owner,true);client=field("client",82,clientValue,true);server=field("server",106,serverValue,true);label=field("label",130,labelValue,false);button("ttl."+ttl,left,154,w,()->{collect();ttl=ttl==3600?86400:ttl==86400?604800:3600;rebuildWidgets();});top=180;}
  else{root=client=server=label=null;top=58;}
  int bw=(w-4)/2;button("preview",left,height-50,bw,()->{collect();service.run(false,owner,clientValue,serverValue,labelValue,ttl);page=1;rebuildWidgets();});author=button("author",left+bw+4,height-50,bw,()->{collect();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)service.run(true,owner,clientValue,serverValue,labelValue,ttl);},tr("confirm_title"),tr("confirm")));});button("back",left,height-26,w,this::onClose);tick();
 }
 private void collect(){if(root!=null){owner=root.getValue().trim();clientValue=client.getValue().trim();serverValue=server.getValue().trim();labelValue=label.getValue().trim();}if(prefs!=null){prefs.addProperty("publication79client",clientValue);prefs.addProperty("publication79server",serverValue);prefs.addProperty("publication79label",labelValue);if(!prefs.equals(DedicatedPanelService75.preferences()))DedicatedPanelService75.save(prefs);}}
 private void browse(EditBox box){collect();Path start;try{start=box.getValue().isBlank()?minecraft.gameDirectory.toPath():Path.of(box.getValue());}catch(Exception bad){start=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,start,p->{box.setValue(p.toString());collect();}));}
 @Override public void tick(){for(Button b:buttons)b.active=!service.busy();for(EditBox e:new EditBox[]{root,client,server,label})if(e!=null)e.setEditable(!service.busy());collect();if(author!=null)author.active=service.canAuthor(owner,clientValue,serverValue,labelValue,ttl);}
 @Override public void removed(){collect();}@Override public void onClose(){if(!service.busy()){collect();minecraft.setScreen(previous);}}@Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){var out=new ArrayList<Component>();String r=service.result();out.add(tr("result."+(Set.of("IDLE","WORKING","PREVIEW","AUTHORED").contains(r)?r:"ERROR")));if(r.startsWith("PUBLICATION79_")){out.add(tr("error."+error(r)));out.add(Component.literal(r));}out.add(tr("full_sets"));if(page==0)return out;
  JsonObject d=service.data();try{if(d.has("authored")){out.add(tr("created",d.get("authored").getAsString()));if(d.has("expires"))out.add(tr("expires",java.time.Instant.ofEpochMilli(Long.parseLong(d.get("expires").getAsString())).toString()));out.add(tr("next"));return out;}if(d.has("seedState"))out.add(tr("seed."+d.get("seedState").getAsString()));for(String k:List.of("game","endpoint","parent","sequence"))if(d.has(k))out.add(tr(k,d.get(k).getAsString()));for(String side:List.of("client","server")){if(d.has(side+"Count")){out.add(tr("set."+side,d.get(side+"Count").getAsString(),d.get(side+"Bytes").getAsString()));for(JsonElement item:d.getAsJsonArray(side))out.add(Component.literal("  "+item.getAsJsonObject().get("path").getAsString()));if(d.get(side+"Count").getAsInt()>20)out.add(tr("more"));}String excluded=side.equals("client")?"excludedClient":"excludedServer";if(d.has(excluded))for(JsonElement e:d.getAsJsonArray(excluded))out.add(tr("excluded",e.getAsString()));}}catch(Exception ignored){}return out;
 }
 private static String error(String r){return switch(r){case "PUBLICATION79_INPUT_CHANGED"->"changed";case "PUBLICATION79_BASELINE_REQUIRED"->"baseline_required";case "PUBLICATION79_LABEL_EXISTS"->"label";case "PUBLICATION79_JAR_SET","PUBLICATION79_MOD_DIRECTORY","PUBLICATION79_LIMIT","PUBLICATION79_BOOTSTRAP_DUPLICATE"->"sets";case "PUBLICATION79_UPDATE_BUSY"->"busy";case "PUBLICATION79_LIVE_SOURCE"->"live";case "PUBLICATION79_IDENTITY","PUBLICATION79_BASELINE","PUBLICATION79_COUNTER_BINDING"->"identity";case "PUBLICATION79_RECOVERED_ROOT","PUBLICATION79_INCOMPLETE_ROOT"->"owner";case "PUBLICATION79_PREVIEW_REQUIRED"->"preview";case "PUBLICATION79_TIMEOUT"->"timeout";default->"generic";};}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);if(page==0){int y=64;for(String key:List.of("root","client","server","label")){g.drawString(font,tr(key),left,y,0xFFCCD0DC,false);y+=24;}}var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(Component line:lines())rows.addAll(font.split(line,w-8));int bottom=Math.max(top,height-56),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var line:rows){if(y+step>=top&&y<bottom)g.drawString(font,line,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
